d.com.vn/thuy-san/#website"},"primaryImageOfPage":{"@id":"https://www.greenfeed.com.vn/thuy-san/wp-content/uploads/2025/05/1.jpg"},"inLanguage":"vi"},{"@type":"Person","@id":"https://www.greenfeed.com.vn/thuy-san/author/gfa_admin/","name":"gfa_admin","url":"https://www.greenfeed.com.vn/thuy-san/author/gfa_admin/","image":{"@type":"ImageObject","@id":"https://secure.gravatar.com/avatar/244296f879a900a601b49468b52c078685f4750af5bb222cb1e0d326836d88f0?s=96&amp;d=mm&amp;r=g","url":"https://secure.gravatar.com/avatar/244296f879a900a601b49468b52c078685f4750af5bb222cb1e0d326836d88f0?s=96&amp;d=mm&amp;r=g","caption":"gfa_admin","inLanguage":"vi"},"sameAs":["http://localhost:8080/thuy-san"]},{"@type":"BlogPosting","headline":"T\u00ecnh tr\u1ea1ng kh\u00e1ng thu\u1ed1c kh\u00e1ng sinh nh\u00f3m Beta-Lactam c\u1ee7a vi khu\u1ea9n g\u00e2y b\u1ec7nh tr\u00ean th\u1ee7y s\u1ea3n: th\u1ef1c tr\u1ea1ng v\u00e0 gi\u1ea3i","keywords":"kh\u00e1ng thu\u1ed1c kh\u00e1ng sinh nh\u00f3m Beta-Lactam","datePublished":"2025-05-19T15:21:45+07:00","dateModified":"2025-05-19T15:23:51+07:00","articleSection":"T\u01b0 li\u1ec7u k\u1ef9 thu\u1eadt","author":{"@id":"https://www.greenfeed.com.vn/thuy-san/author/gfa_admin/","name":"gfa_admin"},"publisher":{"@id":"https://www.greenfeed.com.vn/thuy-san/#person"},"description":"Trong nh\u1eefng n\u0103m g\u1ea7n \u0111\u00e2y, v\u1ea5n \u0111\u1ec1 kh\u00e1ng kh\u00e1ng sinh (AMR - Antimicrobial Resistance) trong nu\u00f4i tr\u1ed3ng th\u1ee7y s\u1ea3n \u0111\u00e3 tr\u1edf th\u00e0nh m\u1ed9t th\u00e1ch th\u1ee9c l\u1edbn \u0111\u1ed1i v\u1edbi ng\u00e0nh c\u00f4ng nghi\u1ec7p th\u1ee7y s\u1ea3n \u1edf Vi\u1ec7t Nam. Vi\u1ec7c l\u1ea1m d\u1ee5ng v\u00e0 s\u1eed d\u1ee5ng kh\u00e1ng sinh kh\u00f4ng \u0111\u00fang trong qu\u00e1 tr\u00ecnh nu\u00f4i tr\u1ed3ng th\u1ee7y s\u1ea3n kh\u00f4ng ch\u1ec9 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn s\u1ee9c kh\u1ecfe c\u1ee7a c\u00e1c lo\u00e0i th\u1ee7y s\u1ea3n m\u00e0 c\u00f2n g\u00e2y ra nh\u1eefng h\u1eadu qu\u1ea3 nghi\u00eam tr\u1ecdng \u0111\u1ed1i v\u1edbi m\u00f4i tr\u01b0\u1eddng v\u00e0 s\u1ee9c kh\u1ecfe con ng\u01b0\u1eddi. Hi\u1ec7n t\u01b0\u1ee3ng kh\u00e1ng kh\u00e1ng sinh x\u1ea3y ra khi vi khu\u1ea9n g\u00e2y b\u1ec7nh tr\u00ean c\u00e1 ng\u00e0y c\u00e0ng x\u1ea3y ra ph\u1ed5 bi\u1ebfn v\u00e0 r\u1ed9ng r\u1ea3i kh\u1eafp m\u1ecdi n\u01a1i v\u00e0 x\u1ea3y ra tr\u00ean t\u1ea5t c\u1ea3 c\u00e1c lo\u00e0i c\u00e1 nu\u00f4i, l\u00e0m gi\u1ea3m hi\u1ec7u qu\u1ea3 \u0111i\u1ec1u tr\u1ecb, gi\u1ea3m n\u0103ng su\u1ea5t nu\u00f4i, gi\u1ea3m l\u1ee3i nhu\u1eadn ho\u1eb7c kh\u00f4ng c\u00f3 l\u1ee3i nhu\u1eadn v\u00e0 \u0111e d\u1ecda \u0111\u1ebfn an to\u00e0n th\u1ef1c ph\u1ea9m.","name":"T\u00ecnh tr\u1ea1ng kh\u00e1ng thu\u1ed1c kh\u00e1ng sinh nh\u00f3m Beta-Lactam c\u1ee7a vi khu\u1ea9n g\u00e2y b\u1ec7nh tr\u00ean th\u1ee7y s\u1ea3n: th\u1ef1c tr\u1ea1ng v\u00e0 gi\u1ea3i","@id":"https://www.greenfeed.com.vn/thuy-san/tinh-trang-khang-thuoc-khang-sinh-nhom-beta-lactam-cua-vi-khuan-gay-benh-tren-thuy-san-thuc-trang-va-giai-phap/#richSnippet","isPartOf":{"@id":"https://www.greenfeed.com.vn/thuy-san/tinh-trang-khang-thuoc-khang-sinh-nhom-beta-lactam-cua-vi-khuan-gay-benh-tren-thuy-san-thuc-trang-va-giai-phap/#webpage"},"image":{"@id":"https://www.greenfeed.com.vn/thuy-san/wp-content/uploads/2025/05/1.jpg"},"inLanguage":"vi","mainEntityOfPage":{"@id":"https://www.greenfeed.com.vn/thuy-san/tinh-trang-khang-thuoc-khang-sinh-nhom-beta-lactam-cua-vi-khuan-gay-benh-tren-thuy-san-thuc-trang-va-giai-phap/#webpage"}}]}
