                            navText:["<div class='nav-btn prev-nav '><img width='28' height='28' src='https://www.greenfeed.com.vn/thuy-san/wp-content/themes/gf-thuysan/assets/images/green-arrow.svg' alt='Prev'></div>","<div class='nav-btn next-nav '><img width='28' height='28' src='https://www.greenfeed.com.vn/thuy-san/wp-content/themes/gf-thuysan/assets/images/green-arrow.svg' alt='Next'></div>"],
                            dots:true,
                            loop:false,
                            margin:30,
                            smartSpeed:450,
                            responsive:{
                                0:{
                                    items:1,
                                    rows:5,
                                    slideBy:1,
                                    margin:0,
                                    stagePadding:0,
                                    nav:false,
                                },
                               1024:{
                                    items:4,
                                    nav:true,
                                    margin:20,
                                    stagePadding:60,
                                },
                                1366:{
                                    items:4,
                                    nav:true,
                                    stagePadding:60,
                                }
                            },
                            onInitialized  : slidecounter,
                            onTranslate : slidecounter
                        };
                        function slidecounter(event) {
                            if(event.type == 'initialized')
                            {
                                var pages     = Math.ceil(event.item.count/event.page.size); 
                                var page      = 1;
                            }
                            else
                            {
                                var pages     = event.page.count; 
                                var page      = event.page.index + 1;
                            }

                            if(page > pages) {
                                page = page - pages
                            }
                            if(pages < 10)
                                pages = '0'+pages;
                            if(page < 10)
                                page = '0'+page;
                            jQuery('.related-posts .carousel-counter').php(page+"/"+pages);
                        }
                        carousel = el.owlCarousel(carouselOptions);
                        var viewport = function() {
                            var width;
                            if (carouselOptions.responsiveBaseElement && carouselOptions.responsiveBaseElement !== window) {
                            width = jQuery(carouselOptions.responsiveBaseElement).width();
                            } else if (window.innerWidth) {
                            width = window.innerWidth;
                            } else if (document.documentElement && document.documentElement.clientWidth) {
                            width = document.documentElement.clientWidth;
                            } else {
                            console.warn('Can not detect viewport width.');
                            }
                            return width;
                        };

                        var severalRows = false;
                        var orderedBreakpoints = [];
                        for (var breakpoint in carouselOptions.responsive) {
                            if (carouselOptions.responsive[breakpoint].rows > 1) {
                            severalRows = true;
                            }
                            orderedBreakpoints.push(parseInt(breakpoint));
                        }
                        if (severalRows) {
                            orderedBreakpoints.sort(function (a, b) {
                            return b - a;
                            });
                            var slides = el.find('[data-slide-index]');
                            var slidesNb = slides.length;
                            if (slidesNb > 0) {
                            var rowsNb;
                            var previousRowsNb = undefined;
                            var colsNb;
                            var previousColsNb = undefined;
                            var updateRowsColsNb = function () {
                                var width =  viewport();
                                for (var i = 0; i < orderedBreakpoints.length; i++) {
                                var breakpoint = orderedBreakpoints[i];
                                if (width >= breakpoint || i == (orderedBreakpoints.length - 1)) {
                                    var breakpointSettings = carouselOptions.responsive['' + breakpoint];
                                    rowsNb = breakpointSettings.rows;
                                    colsNb = breakpointSettings.items;
                                    break;
                                }
                                }
                            };

                            var updateCarousel = function () {
                                updateRowsColsNb();
                                if (rowsNb != previousRowsNb || colsNb != previousColsNb) {
                                var reInit = false;
                                if (carousel) {
                                    carousel.trigger('destroy.owl.carousel');
                                    carousel = undefined;
                                    slides = el.find('[data-slide-index]').detach().appendTo(el);
                                    el.find('.col-wrapper').remove();
                                    reInit = true;
                                }
                                var perPage = rowsNb * colsNb;
                                var pageIndex = Math.floor(slidesNb / perPage);
                                var fakeColsNb = pageIndex * colsNb + (slidesNb >= (pageIndex * perPage + colsNb) ? colsNb : (slidesNb % colsNb));
                                var count = 0;
                                for (var i = 0; i < fakeColsNb; i++) {
                                    var fakeCol = jQuery('<div class="col-wrapper"></div>').appendTo(el);
                                    for (var j = 0; j < rowsNb; j++) {
                                    var index = Math.floor(count / perPage) * perPage + (i % colsNb) + j * colsNb;
                                    if (index < slidesNb) {
                                        slides.filter('[data-slide-index=' + index + ']').detach().appendTo(fakeCol);
                                    }
                                    count++;
                                    }
                                }
                                previousRowsNb = rowsNb;
                                previousColsNb = colsNb;

                                if (reInit) {
                                    carousel = el.owlCarousel(carouselOptions);
                                }
                                }
                            };
                            jQuery(window).on('resize', updateCarousel);
                            updateCarousel();
                            }
                        }
                    }
                    setTimeout(function() { 
                        EqualizeHeights();
                    }, 10);
                    var resizeTimer;
                    $(window).on('resize', function(e) {
                        clearTimeout(resizeTimer);
                        resizeTimer = setTimeout(function() {
                            EqualizeHeights();   
                        }, 250);
                    });
                    function EqualizeHeights() {
                        var max = 0;
                        jQuery('.article__title').each(function (index, value) {
                            max = max_value(max, $(this).find('a').height());
                        });
                        jQuery('.article__title').css('min-height',max+'px');
                    }
                    function max_value($number1,$number2)
                    {
                        return Math.max($number1,$number2);
                    }
				});
     </script>
